@startuml

abstract class Contract {
  + getCharges() : double
  + getBalance() : double
  + setBalance(double)
}

class BasicContract extends Contract {
  + contractNumber : int
  + balance : double
  + getCharges() : double
  + getBalance() : double
  + setBalance(double)
}

abstract class ContractOption extends Contract {}

class DataOption extends ContractOption {
  + getCharges() : double
}

class SmsOption extends ContractOption {
  + getCharges() : double
}

class MinutesOption extends ContractOption {
  + getCharges() : double
}

class DoubleTransferRateOption extends ContractOption {
  + getCharges() : double
}

Contract "1" *-- "0..*" ContractOption

@enduml

